#include "bits/stdc++.h"
using namespace std;
#define all(x) (x).begin(),(x).end()
int main()
{
	ios::sync_with_stdio(0); cin.tie(0);
	int T; cin >> T;
	while (T--)
	{
		int n, i;
		cin >> n;
		vector<int> l(n), r(n), a(n);
		for (i = 0; i < n; i++) cin >> l[i] >> r[i];
		vector e(n, vector<int>(0));
		for (i = 1; i < n; i++)
		{
			int u, v;
			cin >> u >> v;
			--u, --v;
			e[u].push_back(v);
			e[v].push_back(u);
		}
		long long ans = 0;
		function<void(int)> dfs = [&](int u) {
			int mx = l[u];
			for (int v : e[u])
			{
				erase(e[v], u);
				dfs(v);
				mx = max(mx, a[v]);
			}
			a[u] = min(mx, r[u]);
			for (int v : e[u]) ans += max(0, a[v] - a[u]);
		};
		dfs(0);
		cout << ans + a[0] << "\n";
	}
}

for _ in range(int(input())):
	n = int(input())
	l,r=[],[]
	for i in range(n):
		L,R=map(int,input().split())
		l.append(L)
		r.append(R)
	e=[[] for i in range(n)]
	for i in range(n-1):
		u,v=map(int,input().split())
		e[u-1].append(v-1)
		e[v-1].append(u-1)
	stk=[0]
	f=[-1]*n
	nfd=[]
	while stk:
		u=stk.pop()
		nfd.append(u)
		for v in e[u]:
			if v!=f[u]:
				f[v]=u
				stk.append(v)
	nfd.reverse()
	ans=0
	for u in nfd:
		for v in e[u]:
			if f[v]==u:
				l[u]=max(l[u],l[v])
		l[u]=min(l[u],r[u])
		for v in e[u]:
			if f[v]==u:
				ans+=max(0,l[v]-l[u])
	print(ans+l[0])
